import sqlite3, subprocess, re, os
os.chdir('/tmp/uv')
DB='.zk/notebook.db'
con=sqlite3.connect(DB)
con.execute('PRAGMA user_version=8'); con.commit()
tables={'metadata'}
def table_cols(t):
    return [r[1] for r in con.execute(f'PRAGMA table_info({t})')]
for i in range(200):
    p=subprocess.run(['/workspace/executable','list','-q','-P'],capture_output=True,text=True)
    err=p.stderr+p.stdout
    if p.returncode==0:
        print("SUCCESS after",i,"iterations"); print("OUT:",p.stdout[:300]); break
    m=re.search(r'no such table: (\w+)', err)
    if m:
        t=m.group(1)
        try: con.execute(f'CREATE TABLE {t} (id INTEGER PRIMARY KEY)'); con.commit(); tables.add(t); print(i,"+table",t)
        except Exception as e: print(i,"create fail",t,e); break
        continue
    m=re.search(r'no such column: ([\w.]+)', err)
    if m:
        c=m.group(1)
        if '.' in c:
            t,col=c.rsplit('.',1)
        else:
            col=c
            # find a table missing this column - try most recently used: use error SQL context
            t=None
            sqlm=re.search(r'FROM (\w+)', err, re.I)
            if sqlm: t=sqlm.group(1)
            if not t or t not in tables: t=sorted(tables)[-1]
        try:
            con.execute(f'ALTER TABLE {t} ADD COLUMN {col} TEXT'); con.commit(); print(i,"+col",t,col)
        except Exception as e:
            print(i,"alter fail",t,col,e); 
            # try all tables
            done=False
            for tt in list(tables):
                if col not in table_cols(tt):
                    try: con.execute(f'ALTER TABLE {tt} ADD COLUMN {col} TEXT'); con.commit(); print(i,"+col",tt,col); done=True; break
                    except Exception: pass
            if not done: break
        continue
    print(i,"other:",err[:600]); break
print("tables:",{t:table_cols(t) for t in tables})
con.close()
EOF
