import sqlite3, subprocess, json
def mkview(expr):
    con=sqlite3.connect('.zk/notebook.db')
    try: con.execute('DROP VIEW notes_with_metadata')
    except Exception: pass
    con.execute(f'''CREATE VIEW notes_with_metadata AS SELECT id, path, title, metadata, lead, body, raw_content,
     word_count, created, modified, checksum, {expr} as tags FROM notes''')
    con.commit(); con.close()
tests = {'comma':"'a,b'", 'nul':"'a'||char(0)||'b'", 'json':'\'["a","b"]\'', 'soh':"'a'||char(1)||'b'"}
for name,expr in tests.items():
    mkview(expr)
    p=subprocess.run(['/workspace/executable','list','-P','-q','-f','json','--limit','1'],capture_output=True,text=True)
    try: print(name, json.loads(p.stdout)[0]['tags'])
    except Exception: print(name, 'ERR', repr(p.stdout[:80]), repr(p.stderr[:80]))
